export function precedingSpace(node: CodeMirror.SyntaxNode, ast: SDK.CSSPropertyParser.SyntaxTree,
                               matchedResult?: SDK.CSSPropertyParser.BottomUpTreeMatching): string {
  let cur: CodeMirror.SyntaxNode|null = node;
  while (cur && !cur.prevSibling) {
    cur = cur.parent;
  }
  const prev = cur?.prevSibling;
  if (!prev) {
    return '';
  }
  const space = ast.rule.substring(prev.to, node.from);
  if (space || !matchedResult) {
    return space;
  }
  return SDK.CSSPropertyParser.requiresSpace(matchedResult.getComputedText(prev), matchedResult.getComputedText(node)) ?
      ' ' :
      '';
}

export type RendererBase<MatchT extends SDK.CSSPropertyParser.Match> = abstract new () => MatchRenderer<MatchT>;

export interface MatchRenderer<MatchT extends SDK.CSSPropertyParser.Match> {
  readonly matchType: Platform.Constructor.Constructor<MatchT>;
  render(match: MatchT, context: RenderingContext): LitTemplate;
}

// A mixin to automatically expose the match type on specific renrerers

export function rendererBase<MatchT extends SDK.CSSPropertyParser.Match>(
    matchT: Platform.Constructor.Constructor<MatchT>): RendererBase<MatchT> {
  abstract class RendererBaseClass implements MatchRenderer<MatchT> {
    readonly matchType = matchT;
    render(_match: MatchT, _context: RenderingContext): LitTemplate {
      return nothing;
    }
  }
  return RendererBaseClass;
}

/**
 * This class implements highlighting for rendered nodes in value traces. On hover, all nodes belonging to the same
 * Match (using object identity) are highlighted.
 **/
export class Highlighting {
  static readonly REGISTRY_NAME = 'css-value-tracing';
  // This holds a stack of active ranges, the top-stack is the currently highlighted set. mouseenter and mouseleave
  // push and pop range sets, respectively.
  readonly #activeHighlights: Range[][] = [];
  // We hold a bidirectional mapping between nodes and matches. A node can belong to multiple matches when matches are
  // nested (via function arguments for instance).
  readonly #nodesForMatches = new Map<SDK.CSSPropertyParser.Match, Node[][]>();
  readonly #matchesForNodes = new Map<Node, SDK.CSSPropertyParser.Match[]>();
  readonly #registry: Highlight;
  readonly onEnter: (e: Event) => void;
  readonly onExit: (e: Event) => void;

  constructor() {
    const registry = CSS.highlights.get(Highlighting.REGISTRY_NAME);
    this.#registry = registry ?? new Highlight();
    if (!registry) {
      CSS.highlights.set(Highlighting.REGISTRY_NAME, this.#registry);
    }
    this.onExit = this.#onExit.bind(this);
    this.onEnter = this.#onEnter.bind(this);
  }

  registerMatchElement(match: SDK.CSSPropertyParser.Match, element: HTMLElement): void {
    const existingMatches = this.#matchesForNodes.get(element);
    if (existingMatches?.includes(match)) {
      return;
    }
    const ranges = this.#nodesForMatches.get(match);
    if (ranges) {
      ranges.push([element]);
    } else {
      this.#nodesForMatches.set(match, [[element]]);
    }
    if (existingMatches) {
      existingMatches.push(match);
    } else {
      this.#matchesForNodes.set(element, [match]);
    }
  }

  addMatch(match: SDK.CSSPropertyParser.Match, nodes: Node[]): void {
    if (nodes.length > 0) {
      const ranges = this.#nodesForMatches.get(match);
      if (ranges) {
        ranges.push(nodes);
      } else {
        this.#nodesForMatches.set(match, [nodes]);
      }
    }
    for (const node of nodes) {
      const matches = this.#matchesForNodes.get(node);
      if (matches) {
        matches.push(match);
      } else {
        this.#matchesForNodes.set(node, [match]);
      }
      if (node instanceof HTMLElement) {
        node.onmouseenter = this.onEnter;
        node.onmouseleave = this.onExit;
        node.onfocus = this.onEnter;
        node.onblur = this.onExit;
        node.tabIndex = 0;
      }
    }
  }

  * #nodeRangesHitByMouseEvent(e: Event): Generator<Node[]> {
    let hitTabbableMatch = false;
    for (const node of e.composedPath()) {
      const matches = this.#matchesForNodes.get(node as Node);
      if (!matches) {
        continue;
      }
      const isTabbable = node instanceof HTMLElement && node.hasAttribute('tabindex');
      if (hitTabbableMatch && isTabbable) {
        break;
      }
      for (const match of matches) {
        yield* this.#nodesForMatches.get(match) ?? [];
      }
      if (isTabbable) {
        hitTabbableMatch = true;
      }
    }
  }

  #onEnter(e: Event): void {
    this.#registry.clear();
    this.#activeHighlights.push([]);
    for (const nodeRange of this.#nodeRangesHitByMouseEvent(e)) {
      const range = new Range();
      const begin = nodeRange[0];
      const end = nodeRange[nodeRange.length - 1];
      if (begin.parentNode && end.parentNode) {
        range.setStartBefore(begin);
        range.setEndAfter(end);
        this.#activeHighlights[this.#activeHighlights.length - 1].push(range);
        this.#registry.add(range);
      }
    }
  }

  #onExit(): void {
    this.#registry.clear();
    this.#activeHighlights.pop();
    if (this.#activeHighlights.length > 0) {
      this.#activeHighlights[this.#activeHighlights.length - 1].forEach(range => this.#registry.add(range));
    }
  }
}

function highlight(highlighting: Highlighting|undefined, match: SDK.CSSPropertyParser.Match, template: LitTemplate,
                   tabbable = true, autofocus = false): LitTemplate {
  if (!highlighting) {
    return template;
  }
  const register = Directives.ref(element => {
    if (element instanceof HTMLElement) {
      highlighting.registerMatchElement(match, element);
    }
  });
  if (!tabbable) {
    return html`<span ${register}>${template}</span>`;
  }
  return html`<span
      tabindex="0"
      ?autofocus=${autofocus}
      @mouseenter=${highlighting.onEnter}
      @mouseleave=${highlighting.onExit}
      @focus=${highlighting.onEnter}
      @blur=${highlighting.onExit}
      ${register}>${template}</span>`;
}

class LazyEvaluationBlackboard {
  #result?: LitTemplate;
  callback?: (result: LitTemplate) => void;
  readonly #asyncEvalCallback: () => Promise<LitTemplate|null>;

  constructor(asyncEvalCallback: () => Promise<LitTemplate|null>) {
    this.#asyncEvalCallback = asyncEvalCallback;
  }

  get result(): LitTemplate|undefined {
    return this.#result;
  }

  set result(val: LitTemplate) {
    if (this.#result === val) {
      return;
    }
    this.#result = val;
    this.callback?.(val);
  }

  readonly asyncEvalCallback = async(): Promise<boolean> => {
    const result = await this.#asyncEvalCallback();
    if (result) {
      this.result = result;
    }
    return Boolean(result);
  };
}

class LazyEvaluationDirective extends AsyncDirective.AsyncDirective {
  render(
      placeholder: LitTemplate,
      blackboard: LazyEvaluationBlackboard,
      ): LitTemplate {
    blackboard.callback = result => {
      if (this.isConnected) {
        this.setValue(result);
      }
    };
    return blackboard.result ?? placeholder;
  }
}
const lazyEvaluation = AsyncDirective.directive(LazyEvaluationDirective);
/**
 * This class is used to guide value tracing when passed to the Renderer. Tracing has two phases. First, substitutions
 * such as var() are applied step by step. In each step, all vars in the value are replaced by their definition until no
 * vars remain. In the second phase, we evaluate other functions such as calc() or min() or color-mix(). Which CSS
 * function types are actually substituted or evaluated is not relevant here, rather it is decided by an individual
 * MatchRenderer.
 *
 * Callers don't need to keep track of the tracing depth (i.e., the number of substitution/evaluation steps).
 * TracingContext is stateful and keeps track of the depth, so callers can progressively produce steps by calling
 * TracingContext#nextSubstitution or TracingContext#nextEvaluation. Calling Renderer with the tracing context will then
 * produce the next step of tracing. The tracing depth is passed to the individual MatchRenderers by way of
 * TracingContext#substitution or TracingContext#applyEvaluation/TracingContext#evaluation (see function-level comments
 * about how these two play together), which MatchRenderers call to request a fresh TracingContext for the next level of
 * substitution/evaluation.
 **/
export class TracingContext {
  #substitutionDepth = 0;
  #hasMoreSubstitutions: boolean;
  #parent: TracingContext|null = null;
  #evaluationCount = 0;
  #appliedEvaluations = 0;
  #hasMoreEvaluations = true;
  #longhandOffset: number;
  readonly #highlighting: Highlighting;
  #parsedValueCache = new Map<SDK.CSSProperty.CSSProperty|SDK.CSSMatchedStyles.CSSRegisteredProperty, {
    matchedStyles: SDK.CSSMatchedStyles.CSSMatchedStyles,
    computedStyles: Map<string, string>,
    parsedValue: SDK.CSSPropertyParser.BottomUpTreeMatching|null,
  }>();
  #root: {match: SDK.CSSPropertyParser.Match, context: RenderingContext}|null = null;
  #propertyName: string|null;
  #asyncEvalCallbacks: Array<(() => Promise<boolean>)|undefined> = [];
  #autofocusNextMatch = false;
  #matchStack: Array<{autofocus: boolean, hasChildMatch: boolean, substituted: boolean}> = [];
  readonly expandPercentagesInShorthands: boolean;

  constructor(highlighting: Highlighting, expandPercentagesInShorthands: boolean, initialLonghandOffset = 0,
              matchedResult?: SDK.CSSPropertyParser.BottomUpTreeMatching) {
    this.#highlighting = highlighting;
    this.#hasMoreSubstitutions = matchedResult?.hasMatches(SDK.CSSPropertyParserMatchers.VariableMatch,
                                                           SDK.CSSPropertyParserMatchers.BaseVariableMatch,
                                                           SDK.CSSPropertyParserMatchers.AttributeMatch,
                                                           SDK.CSSPropertyParserMatchers.EnvFunctionMatch) ??
        false;
    this.#propertyName = matchedResult?.ast.propertyName ?? null;
    this.#longhandOffset = initialLonghandOffset;
    this.expandPercentagesInShorthands = expandPercentagesInShorthands;
  }

  #rootTracing(): TracingContext {
    return this.#parent ? this.#parent.#rootTracing() : this;
  }

  enableAutofocusOnFirstMatch(): void {
    this.#rootTracing().#autofocusNextMatch = true;
  }

  beginMatch(): void {
    const root = this.#rootTracing();
    const parentFrame = root.#matchStack.at(-1);
    let autofocus = false;
    if (parentFrame?.substituted && parentFrame.autofocus && !parentFrame.hasChildMatch) {
      autofocus = true;
      parentFrame.autofocus = false;
    } else if (root.#autofocusNextMatch) {
      autofocus = true;
      root.#autofocusNextMatch = false;
    }
    if (parentFrame) {
      parentFrame.hasChildMatch = true;
    }
    root.#matchStack.push({autofocus, hasChildMatch: false, substituted: false});
  }

  endMatch(hasOutput: boolean): {substituted: boolean, autofocus: boolean} {
    const root = this.#rootTracing();
    const frame = root.#matchStack.pop();
    if (!frame) {
      return {substituted: false, autofocus: false};
    }
    const substituted = frame.substituted && frame.hasChildMatch;
    if (!hasOutput && frame.autofocus) {
      root.#autofocusNextMatch = true;
    }
    return {substituted, autofocus: hasOutput && !substituted && frame.autofocus};
  }

  get highlighting(): Highlighting {
    return this.#highlighting;
  }

  get root(): {match: SDK.CSSPropertyParser.Match, context: RenderingContext}|null {
    return this.#root;
  }

  get propertyName(): string|null {
    return this.#propertyName;
  }

  get longhandOffset(): number {
    return this.#longhandOffset;
  }

  renderingContext(context: RenderingContext): RenderingContext {
    return new RenderingContext(context.ast, context.property, context.renderers, context.matchedResult,
                                context.cssControls, context.options, this);
  }

  nextSubstitution(): boolean {
    if (!this.#hasMoreSubstitutions) {
      return false;
    }
    this.#substitutionDepth++;
    this.#hasMoreSubstitutions = false;
    this.#asyncEvalCallbacks = [];
    return true;
  }

  nextEvaluation(): boolean {
    if (this.#hasMoreSubstitutions) {
      throw new Error('Need to apply substitutions first');
    }
    if (!this.#hasMoreEvaluations) {
      return false;
    }
    this.#appliedEvaluations = 0;
    this.#hasMoreEvaluations = false;
    this.#evaluationCount++;
    this.#asyncEvalCallbacks = [];
    return true;
  }

  #setHasMoreEvaluations(value: boolean): void {
    if (this.#parent) {
      this.#parent.#setHasMoreEvaluations(value);
    }
    this.#hasMoreEvaluations = value;
  }

  // Evaluations are applied bottom up, i.e., innermost sub-expressions are evaluated first before evaluating any
  // function call. This function produces TracingContexts for each of the arguments of the function call which should
  // be passed to the Renderer calls for the respective subtrees.
  evaluation(args: unknown[],
             root: {match: SDK.CSSPropertyParser.Match, context: RenderingContext}|null = null): TracingContext[]|null {
    const childContexts = args.map(() => {
      const child = new TracingContext(this.#highlighting, this.expandPercentagesInShorthands);
      child.#parent = this;
      child.#substitutionDepth = this.#substitutionDepth;
      child.#evaluationCount = this.#evaluationCount;
      child.#hasMoreSubstitutions = this.#hasMoreSubstitutions;
      child.#parsedValueCache = this.#parsedValueCache;
      child.#root = root;
      child.#propertyName = this.propertyName;
      return child;
    });
    return childContexts;
  }

  #setAppliedEvaluations(value: number): void {
    if (this.#parent) {
      this.#parent.#setAppliedEvaluations(value);
    }
    this.#appliedEvaluations = Math.max(this.#appliedEvaluations, value);
  }

  // After rendering the arguments of a function call, the TracingContext produced by TracingContext#evaluation need to
  // be passed here to determine whether the "current" function call should be evaluated or not. If so, the
  // evaluation callback is run. The callback should return synchronously a template as placeholder to be
  // rendered immediately and optionally a callback for asynchronous updates of the template.
  applyEvaluation(children: TracingContext[],
                  evaluation: () => {template: LitTemplate, asyncEvalCallback?: () => Promise<LitTemplate|null>}):
      LitTemplate|null {
    if (this.#evaluationCount === 0 || children.some(child => child.#appliedEvaluations >= this.#evaluationCount)) {
      this.#setHasMoreEvaluations(true);
      children.forEach(child => this.#asyncEvalCallbacks.push(...child.#asyncEvalCallbacks));
      return null;
    }
    this.#setAppliedEvaluations(children.map(child => child.#appliedEvaluations).reduce((a, b) => Math.max(a, b), 0) +
                                1);
    const result = evaluation();
    if (!result.asyncEvalCallback) {
      this.#asyncEvalCallbacks.push(result.asyncEvalCallback);
      return result.template;
    }

    const blackboard = new LazyEvaluationBlackboard(result.asyncEvalCallback);
    this.#asyncEvalCallbacks.push(blackboard.asyncEvalCallback);
    return html`${lazyEvaluation(result.template, blackboard)}`;
  }

  #setHasMoreSubstitutions(): void {
    if (this.#parent) {
      this.#parent.#setHasMoreSubstitutions();
    }
    this.#hasMoreSubstitutions = true;
  }

  // Request a tracing context for the next level of substitutions. If this returns null, no further substitution should
  // be applied on this branch of the AST. Otherwise, the TracingContext should be passed to the Renderer call for the
  // substitution subtree.
  substitution(root: {match: SDK.CSSPropertyParser.Match, context: RenderingContext}|null = null): TracingContext|null {
    if (this.#substitutionDepth <= 0) {
      this.#setHasMoreSubstitutions();
      return null;
    }
    const parentFrame = this.#rootTracing().#matchStack.at(-1);
    if (parentFrame) {
      parentFrame.substituted = true;
    }
    const child = new TracingContext(this.#highlighting, this.expandPercentagesInShorthands);
    child.#parent = this;
    child.#substitutionDepth = this.#substitutionDepth - 1;
    child.#evaluationCount = this.#evaluationCount;
    child.#hasMoreSubstitutions = false;
    child.#parsedValueCache = this.#parsedValueCache;
    child.#root = root;
    // Async evaluation callbacks need to be gathered across substitution contexts so that they bubble to the root. That
    // is not the case for evaluation contexts since `applyEvaluation` conditionally collects callbacks for its subtree
    // already.
    child.#asyncEvalCallbacks = this.#asyncEvalCallbacks;
    child.#longhandOffset =
        this.#longhandOffset + (root?.context.matchedResult.getComputedLonghandName(root?.match.node) ?? 0);
    child.#propertyName = this.propertyName;
    return child;
  }

  cachedParsedValue(declaration: SDK.CSSProperty.CSSProperty|SDK.CSSMatchedStyles.CSSRegisteredProperty,
                    matchedStyles: SDK.CSSMatchedStyles.CSSMatchedStyles,
                    computedStyles: Map<string, string>): SDK.CSSPropertyParser.BottomUpTreeMatching|null {
    const cachedValue = this.#parsedValueCache.get(declaration);
    if (cachedValue?.matchedStyles === matchedStyles && cachedValue?.computedStyles === computedStyles) {
      return cachedValue.parsedValue;
    }
    const parsedValue = declaration.parseValue(matchedStyles, computedStyles);
    this.#parsedValueCache.set(declaration, {matchedStyles, computedStyles, parsedValue});
    return parsedValue;
  }

  // If this returns `false`, all evaluations for this trace line have failed.
  async runAsyncEvaluations(): Promise<boolean> {
    const results = await Promise.all(this.#asyncEvalCallbacks.map(callback => callback?.()));
    return results.some(result => result !== false);
  }
}

export const CSSControlMap: MapConstructor = Map;
export type CSSControlMap = Map<string, HTMLElement[]>;

/**
 * Records that the text of `original` was modified to `value`, e.g. because the user changed it in an editor. In a
 * `ComputedText`, a ValueEdit stands in for `original`: it takes over the range of `original` and substitutes `value`
 * for its text. This keeps modifications separate from `original.computedText()`, which stands for the result of
 * resolving var()s, stripping comments and the like.
 *
 * A function as `value` is called whenever the text is read. This is for renderers that put the text of their match
 * together from parts that keep changing.
 **/
class ValueEdit implements SDK.CSSPropertyParser.Match {
  value: string|(() => string);

  constructor(readonly original: SDK.CSSPropertyParser.Match, value: string|(() => string)) {
    this.value = value;
  }

  get text(): string {
    return this.original.text;
  }

  get node(): CodeMirror.SyntaxNode {
    return this.original.node;
  }

  computedText(): string {
    return typeof this.value === 'string' ? this.value : this.value();
  }
}

/**
 * Tracks the changes that renderers make to the text of the value of a declaration, e.g. because the user picked a
 * color, and puts the text of the value together from them. It wraps a `ComputedText` over the authored text of the
 * declaration, in which a change takes the place of the match that it replaces.
 **/
export class ValueUpdateTracking {
  readonly #text: SDK.CSSPropertyParser.ComputedText;
  // A match is pushed to the text once, later changes of it update its edit. See `#get` for how they get picked up.
  readonly #edits = new Map<SDK.CSSPropertyParser.Match, ValueEdit>();
  // The text spans the whole declaration, including the name of the property and the trailing ';}'. Offsets in it are
  // relative to the start of the declaration, whereas the AST that a renderer works on may be a subtree of it.
  readonly #declarationStart: number;
  // The value in the text: from the first node after the colon to the last node of the declaration, which may be a
  // comment that follows the value.
  readonly #valueBegin: number;
  readonly #valueEnd: number;

  constructor(ast: SDK.CSSPropertyParser.SyntaxTree) {
    const {siblings, declValue, range} = SDK.CSSPropertyParser.ASTUtils;
    const {tree, trailingNodes} = ast;
    const [first, last] = range(siblings(declValue(tree)));
    const end = trailingNodes.at(-1) ?? last;
    this.#declarationStart = tree.from;
    this.#text = new SDK.CSSPropertyParser.ComputedText(ast.rule.substring(tree.from));
    if (first && end) {
      this.#valueBegin = first.from - tree.from;
      this.#valueEnd = end.to - tree.from;
    } else {
      // Without a value, the range is empty.
      this.#valueBegin = 0;
      this.#valueEnd = 0;
    }
  }

  // Records that the text of `match` was changed to `value`. This replaces the change of `match` that was recorded
  // before, if any. A function is called every time the text is read.
  recordEdit(match: SDK.CSSPropertyParser.Match, value: string|(() => string)): void {
    const existing = this.#edits.get(match);
    if (existing) {
      existing.value = value;
      return;
    }
    const edit = new ValueEdit(match, value);
    this.#edits.set(match, edit);
    // A match of the whole declaration stands for its value, which starts after the name of the property.
    const offset = match.node.name === 'Declaration' ? this.#valueBegin : match.node.from - this.#declarationStart;
    this.#text.push(edit, offset);
  }

  // The text of the value with the recorded changes applied.
  valueText(): string {
    return this.#get(this.#valueBegin, this.#valueEnd);
  }

  getEdit(match: SDK.CSSPropertyParser.Match): string|undefined {
    return this.#edits.get(match)?.computedText();
  }

  // The text of the nodes `from` to `to` with the recorded changes applied, like `SyntaxTree.textRange` for the authored
  // text.
  textRange(from: CodeMirror.SyntaxNode|undefined, to: CodeMirror.SyntaxNode|undefined): string {
    if (!from || !to) {
      return '';
    }
    return this.#get(from.from - this.#declarationStart, to.to - this.#declarationStart);
  }

  // A `ComputedText` remembers the text of a chunk after reading it for the first time, which would hide later changes
  // of an edit. Asking the edits for their text through the substitution hook avoids that.
  #get(begin: number, end: number): string {
    return this.#text.get(begin, end, match => match.computedText?.() ?? null);
  }
}

export class ValueEditEvent extends CustomEvent<string> {
  static readonly eventName = 'valueedit';

  constructor(value: string) {
    super(ValueEditEvent.eventName, {bubbles: true, detail: value});
  }
}

export interface ViewInput {
  editedValue: string|null;
  onValueEdit: (value: string) => void;
}

export type View = (input: ViewInput, output: undefined, target: HTMLElement|DocumentFragment) => void;

export const DEFAULT_VIEW: View = (input, _output, target) => {
  const onValueEdit = (event: ValueEditEvent): void => {
    event.stopPropagation();
    input.onValueEdit(event.detail);
  };
  render(html`<slot name="icon" @valueedit=${onValueEdit}></slot>${input.editedValue ?? html`<slot></slot>`}`, target);
};

/**
 * Hosts a value part that can be edited through an inline swatch or icon.
 *
 * The swatch or icon goes into the `icon` slot, and the initial rendered AST nodes go into the default slot. When the
 * swatch or icon dispatches a `ValueEditEvent`, the default slot is replaced with the new text while the `icon` slot
 * stays in place.
 **/
export class EditableContent extends UI.Widget.Widget<DocumentFragment> {
  #editedValue: string|null = null;
  readonly #view: View;

  constructor(element?: HTMLElement, view: View = DEFAULT_VIEW) {
    super(element, {useShadowDom: 'pure'});
    this.element.classList.remove('widget');
    this.#view = view;
    // Render synchronously so that `<slot name="icon">` is in the DOM before synchronous callers dispatch edits.
    this.performUpdate();
  }

  #onValueEdit = (value: string): void => {
    if (this.#editedValue === value) {
      return;
    }
    this.#editedValue = value;
    // Render synchronously so that synchronous callers (e.g. `renderedPropertyText()`) observe the updated text immediately.
    this.performUpdate();
  };

  override performUpdate(): void {
    this.#view({editedValue: this.#editedValue, onValueEdit: this.#onValueEdit}, undefined, this.contentElement);
  }
}

export class RenderingContext {
  constructor(readonly ast: SDK.CSSPropertyParser.SyntaxTree, readonly property: SDK.CSSProperty.CSSProperty|null,
              readonly renderers: Map<Platform.Constructor.Constructor<SDK.CSSPropertyParser.Match>,
                                      MatchRenderer<SDK.CSSPropertyParser.Match>>,
              readonly matchedResult: SDK.CSSPropertyParser.BottomUpTreeMatching,
              readonly cssControls?: CSSControlMap|undefined, readonly options: {readonly?: boolean} = {},
              readonly tracing?: TracingContext|undefined, readonly signal?: AbortSignal|undefined,
              readonly edits?: ValueUpdateTracking|undefined) {
  }

  // Records that a renderer changed the text of `match` to `value`, e.g. because the user picked a color, so that the
  // change becomes part of the text of the property. A function is called every time the text of the property is put
  // together. Does nothing if the context doesn't track changes, e.g. for value traces.
  recordEdit(match: SDK.CSSPropertyParser.Match, value: string|(() => string)): void {
    this.edits?.recordEdit(match, value);
  }

  addControl(cssType: string, control: HTMLElement): void {
    if (this.cssControls) {
      const controls = this.cssControls.get(cssType);
      if (!controls) {
        this.cssControls.set(cssType, [control]);
      } else {
        controls.push(control);
      }
    }
  }

  getComputedLonghandName(node: CodeMirror.SyntaxNode): string|null {
    if (!this.matchedResult.ast.propertyName) {
      return null;
    }
    const longhands =
        SDK.CSSMetadata.cssMetadata().getLonghands(this.tracing?.propertyName ?? this.matchedResult.ast.propertyName);
    if (!longhands) {
      return null;
    }
    const index = this.matchedResult.getComputedLonghandName(node);
    return longhands[index + (this.tracing?.longhandOffset ?? 0)] ?? null;
  }

  findParent<MatchT extends SDK.CSSPropertyParser.Match>(node: CodeMirror.SyntaxNode|null,
                                                         matchType: Platform.Constructor.Constructor<MatchT>): MatchT
      |null {
    while (node) {
      const match = this.matchedResult.getMatch(node);
      if (match instanceof matchType) {
        return match;
      }
      node = node.parent;
    }
    if (this.tracing?.root) {
      return this.tracing.root.context.findParent(this.tracing.root.match.node, matchType);
    }
    return null;
  }
}

export class Renderer extends SDK.CSSPropertyParser.TreeWalker {
  readonly #matchedResult: SDK.CSSPropertyParser.BottomUpTreeMatching;
  #output: LitTemplate[] = [];
  readonly #context: RenderingContext;

  constructor(
      ast: SDK.CSSPropertyParser.SyntaxTree,
      property: SDK.CSSProperty.CSSProperty|null,
      renderers: Map<Platform.Constructor.Constructor<SDK.CSSPropertyParser.Match>,
                     MatchRenderer<SDK.CSSPropertyParser.Match>>,
      matchedResult: SDK.CSSPropertyParser.BottomUpTreeMatching,
      cssControls: CSSControlMap,
      options: {
        readonly?: boolean,
      },
      tracing: TracingContext|undefined,
      signal: AbortSignal|undefined,
      edits: ValueUpdateTracking|undefined,
  ) {
    super(ast);
    this.#matchedResult = matchedResult;
    this.#context = new RenderingContext(this.ast, property, renderers, this.#matchedResult, cssControls, options,
                                         tracing, signal, edits);
  }

  static render(nodeOrNodes: CodeMirror.SyntaxNode|CodeMirror.SyntaxNode[],
                context: RenderingContext): {nodes: LitTemplate, cssControls: CSSControlMap} {
    if (!Array.isArray(nodeOrNodes)) {
      return this.render([nodeOrNodes], context);
    }
    const cssControls = new CSSControlMap();
    const renderers =
        nodeOrNodes.map(node => this.walkExcludingSuccessors(
                            context.ast.subtree(node), context.property, context.renderers, context.matchedResult,
                            cssControls, context.options, context.tracing, context.signal, context.edits));
    const nodes = renderers.reduce((nodes: LitTemplate[], renderer) => {
      if (renderer !== renderers[0]) {
        const spacing = precedingSpace(renderer.ast.tree, context.ast, context.matchedResult);
        if (spacing) {
          nodes.push(html`${spacing}`);
        }
      }
      nodes.push(...renderer.#output);
      return nodes;
    }, []);
    return {nodes: html`${nodes}`, cssControls};
  }

  renderedMatchForTest(_nodes: LitTemplate, _match: SDK.CSSPropertyParser.Match): void {
  }

  protected override enter({node}: SDK.CSSPropertyParser.SyntaxNodeRef): boolean {
    const match = this.#matchedResult.getMatch(node);
    const renderer = match &&
        this.#context.renderers.get(match.constructor as Platform.Constructor.Constructor<SDK.CSSPropertyParser.Match>);
    if (renderer || match instanceof SDK.CSSPropertyParserMatchers.TextMatch) {
      this.#context.tracing?.beginMatch();
      const rendered = renderer?.render(match, this.#context) ?? html`<span>${match.text}</span>`;
      const {substituted, autofocus} =
          this.#context.tracing?.endMatch(rendered !== nothing) ?? {substituted: false, autofocus: false};
      const output = rendered === nothing ?
          nothing :
          highlight(this.#context.tracing?.highlighting, match, rendered, !substituted, autofocus);
      this.renderedMatchForTest(output, match);
      if (this.#output.some(t => t !== nothing)) {
        const spacing = precedingSpace(node, this.#context.ast, this.#matchedResult);
        if (spacing) {
          this.#output.push(html`${spacing}`);
        }
      }
      this.#output.push(output);

      return false;
    }

    return true;
  }

  static renderNameElement(name: string): HTMLElement {
    const fragment = document.createDocumentFragment();
    render(this.nameTemplate(name), fragment);
    const nameElement = fragment.firstElementChild as HTMLElement;
    // Detach from the render fragment so callers get a standalone element.
    nameElement.remove();
    nameElement.normalize();
    return nameElement;
  }

  static nameTemplate(name: string): LitTemplate {
    // clang-format off
    return html`<span
      jslog=${VisualLogging.key().track({
        change: true,
        keydown: 'ArrowLeft|ArrowUp|PageUp|Home|PageDown|ArrowRight|ArrowDown|End|Space|Tab|Enter|Escape',
      })}
      aria-label=${i18nString(UIStrings.cssPropertyName, {PH1: name})}
      class="webkit-css-property"
      tabindex="-1"
    >${name}</span>`;
    // clang-format on
  }

  // This function renders a property value as HTML, customizing the presentation with a set of given AST matchers. This
  // comprises the following steps:
  // 1. Build an AST of the property.
  // 2. Apply tree matchers during bottom up traversal.
  // 3. Render the value from left to right into HTML, deferring rendering of matched subtrees to the matchers
  //
  // More general, longer matches take precedence over shorter, more specific matches. Whitespaces are normalized, for
  // unmatched text and around rendered matching results.
  //
  // The renderers record the changes they make to the text of the value in `edits`, if given, see
  // `RenderingContext.recordEdit`.
  static renderValueElement(property: SDK.CSSProperty.CSSProperty|{name: string, value: string},
                            matchedResult: SDK.CSSPropertyParser.BottomUpTreeMatching|null,
                            renderers: Array<MatchRenderer<SDK.CSSPropertyParser.Match>>, tracing?: TracingContext,
                            signal?: AbortSignal,
                            edits?: ValueUpdateTracking): {valueElement: HTMLElement, cssControls: CSSControlMap} {
    const {template, cssControls} = this.valueTemplate(property, matchedResult, renderers, tracing, signal, edits);
    const fragment = document.createDocumentFragment();
    render(template, fragment);
    const valueElement = fragment.firstElementChild as HTMLElement;
    // Detach from the render fragment so callers get a standalone element.
    valueElement.remove();
    valueElement.normalize();
    return {valueElement, cssControls};
  }

  static valueTemplate(property: SDK.CSSProperty.CSSProperty|{name: string, value: string},
                       matchedResult: SDK.CSSPropertyParser.BottomUpTreeMatching|null,
                       renderers: Array<MatchRenderer<SDK.CSSPropertyParser.Match>>, tracing?: TracingContext,
                       signal?: AbortSignal,
                       edits?: ValueUpdateTracking): {template: LitTemplate, cssControls: CSSControlMap} {
    const {nodes, cssControls} = this.renderValueNodes(property, matchedResult, renderers, tracing, signal, edits);
    // clang-format off
    const template = html`<span
      jslog=${VisualLogging.value().track({
        change: true,
        keydown: 'ArrowLeft|ArrowUp|PageUp|Home|PageDown|ArrowRight|ArrowDown|End|Space|Tab|Enter|Escape',
      })}
      aria-label=${i18nString(UIStrings.cssPropertyValue, {PH1: property.value})}
      class="value"
      tabindex="-1"
    >${nodes}</span>`;
    // clang-format on
    return {template, cssControls};
  }

  static renderValueNodes(property: SDK.CSSProperty.CSSProperty|{name: string, value: string},
                          matchedResult: SDK.CSSPropertyParser.BottomUpTreeMatching|null,
                          renderers: Array<MatchRenderer<SDK.CSSPropertyParser.Match>>, tracing?: TracingContext,
                          signal?: AbortSignal,
                          edits?: ValueUpdateTracking): {nodes: LitTemplate, cssControls: CSSControlMap} {
    if (!matchedResult) {
      return {nodes: html`${property.value}`, cssControls: new Map()};
    }
    const rendererMap = new Map<Platform.Constructor.Constructor<SDK.CSSPropertyParser.Match>,
                                MatchRenderer<SDK.CSSPropertyParser.Match>>();
    for (const renderer of renderers) {
      rendererMap.set(renderer.matchType, renderer);
    }

    const context =
        new RenderingContext(matchedResult.ast, property instanceof SDK.CSSProperty.CSSProperty ? property : null,
                             rendererMap, matchedResult, undefined, {}, tracing, signal, edits);
    return Renderer.render([matchedResult.ast.tree, ...matchedResult.ast.trailingNodes], context);
  }
}

const URLRendererBase: RendererBase<SDK.CSSPropertyParserMatchers.URLMatch> =
    rendererBase(SDK.CSSPropertyParserMatchers.URLMatch);
// clang-format off
export class URLRenderer extends URLRendererBase {
  // clang-format on
  readonly #rule: SDK.CSSRule.CSSRule|null;
  readonly #node: SDK.DOMModel.DOMNode|null;
  constructor(rule: SDK.CSSRule.CSSRule|null, node: SDK.DOMModel.DOMNode|null) {
    super();
    this.#rule = rule;
    this.#node = node;
  }
  override render(match: SDK.CSSPropertyParserMatchers.URLMatch): LitTemplate {
    const url = unescapeCssString(match.url) as Platform.DevToolsPath.UrlString;
    let hrefUrl: Platform.DevToolsPath.UrlString|null = null;
    if (this.#rule?.resourceURL()) {
      hrefUrl = Common.ParsedURL.ParsedURL.completeURL(this.#rule.resourceURL(), url);
    } else if (this.#node) {
      hrefUrl = this.#node.resolveURL(url);
    }
    const link = ImagePreviewPopover.setImageUrl(Components.Linkifier.Linkifier.linkifyURL(hrefUrl || url, {
      text: url,
      preventClick: false,
      // crbug.com/1027168
      // We rely on CSS text-overflow: ellipsis to hide long URLs in the Style panel,
      // so that we don't have to keep two versions (original vs. trimmed) of URL
      // at the same time, which complicates both StylesSidebarPane and StylePropertyTreeElement.
      bypassURLTrimming: true,
      showColumnNumber: false,
    }),
                                                 hrefUrl || url);
    return html`url(${link})`;
  }
}

const StringRendererBase: RendererBase<SDK.CSSPropertyParserMatchers.StringMatch> =
    rendererBase(SDK.CSSPropertyParserMatchers.StringMatch);
// clang-format off
export class StringRenderer extends StringRendererBase {
  // clang-format on
  override render(match: SDK.CSSPropertyParserMatchers.StringMatch): LitTemplate {
    return html`<span title=${unescapeCssString(match.text)}>${match.text}</span>`;
  }
}

const BinOpRendererBase: RendererBase<SDK.CSSPropertyParserMatchers.BinOpMatch> =
    rendererBase(SDK.CSSPropertyParserMatchers.BinOpMatch);
// clang-format off
export class BinOpRenderer extends BinOpRendererBase {
  // clang-format on
  override render(match: SDK.CSSPropertyParserMatchers.BinOpMatch, context: RenderingContext): LitTemplate {
    const [lhs, binop, rhs] = SDK.CSSPropertyParser.ASTUtils.children(match.node)
                                  .map(child => html`<span>${Renderer.render(child, context).nodes}</span>`);

    return html`${lhs} ${binop} ${rhs}`;
  }
}
